SELECT objRec.* FROM ( SELECT PROD_ID, MDATE, BALANCE_AMT, PRD_QTY FROM( SELECT @rownum :=@rownum +1 rownum, PROD_ID, MDATE, BALANCE_AMT, PRD_QTY, IF (@PROD_ID = PROD_ID, @rank :=@rank + 1, @rank :=1 ) AS durMDateNo, @PROD_ID := PROD_ID FROM (SELECT * FROM ( SELECT A.PROD_ID, B.MDATE, B.BALANCE_AMT, B.PRD_QTY, ROW_NUMBER() over( partition by A.PROD_ID , B.MDATE ORDER BY B.UPDATE_TIME DESC) AS durStatusNo FROM CHB_PRD_BASEINFO A INNER JOIN CHB_PRD_DEAL_SUB B ON A.PROD_ID = B.PROD_ID WHERE A.STATUS != 'D'
#{orgCode,jdbcType=VARCHAR}
#{operateMode,jdbcType=VARCHAR}
AND A.FPROD_ID is null AND STR_TO_DATE(DATE_FORMAT(B.MDATE, '%Y-%m-%d'), '%Y-%m-%d') <= STR_TO_DATE(#{searchDate,jdbcType=VARCHAR},'%Y-%m-%d') ) AA ORDER BY PROD_ID, MDATE ) TMP, (SELECT @rownum :=0, @PROD_ID := NULL, @rank := 0) CC WHERE durStatusNo = 1 ) TMP1 WHERE durMDateNo = 1 OR durMDateNo = 2 ) objRec
